PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS config(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nodes(id TEXT PRIMARY KEY,parent TEXT REFERENCES nodes(id),name TEXT NOT NULL,path TEXT NOT NULL,kind TEXT NOT NULL,size INTEGER NOT NULL,mtime INTEGER NOT NULL,dev INTEGER NOT NULL,ino INTEGER NOT NULL,deleted INTEGER NOT NULL DEFAULT 0,mtime_ns INTEGER NOT NULL,uploaded_at INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS live_names ON nodes(parent,name) WHERE deleted=0;
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,expires INTEGER NOT NULL,generation TEXT NOT NULL,csrf TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_audit(id INTEGER PRIMARY KEY,time INTEGER NOT NULL,success INTEGER NOT NULL,ip TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'invalid_credentials');
CREATE TABLE IF NOT EXISTS shares(id TEXT PRIMARY KEY,hash TEXT UNIQUE NOT NULL,root TEXT NOT NULL REFERENCES nodes(id),expires INTEGER,revoked INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,encrypted_token TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS uploads(id TEXT PRIMARY KEY,parent TEXT NOT NULL REFERENCES nodes(id),name TEXT NOT NULL,size INTEGER NOT NULL,digest TEXT NOT NULL,strategy TEXT NOT NULL,expires INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'pending',node TEXT);
CREATE TABLE IF NOT EXISTS chunks(upload TEXT NOT NULL REFERENCES uploads(id) ON DELETE CASCADE,idx INTEGER NOT NULL,digest TEXT NOT NULL,size INTEGER NOT NULL,PRIMARY KEY(upload,idx));
CREATE TABLE IF NOT EXISTS trash(id TEXT PRIMARY KEY REFERENCES nodes(id),parent TEXT NOT NULL,name TEXT NOT NULL,path TEXT NOT NULL,deleted_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS operations(id TEXT PRIMARY KEY,payload TEXT NOT NULL);
